     }

     h1,
     h2,
     p {
       margin: 0;
     }

     .title-row {
       margin-top: 16px;
       display: flex;
       justify-content: space-between;
       align-items: start;
       gap: 16px;
     }

     .title-row h1 {
       font-size: clamp(1.8rem, 4vw, 2.6rem);
       line-height: 1.05;
     }

     .meta {
       margin-top: 16px;
       color: var(--muted);
       font-size: 0.96rem;
       line-height: 1.7;
     }

     .actions {
       margin-top: 24px;
       display: flex;
       align-items: center;
       gap: 14px;
       flex-wrap: wrap;
     }

     button {
       appearance: none;
       border: 0;
       cursor: pointer;
       font: inherit;
       transition: transform 140ms ease, background-color 140ms ease, box-shadow 140ms ease, opacity 140ms ease;
     }

     button:hover {
       transform: translateY(-1px);
     }

     button:focus-visible {
       outline: 2px solid var(--accent);
       outline-offset: 3px;
     }

     .button {
       min-width: 132px;
       padding: 14px 18px;
       border-radius: 14px;
       font-weight: 700;
     }

     .trigger {
       background: linear-gradient(180deg, var(--danger) 0%, var(--danger-strong) 100%);
       color: white;
       box-shadow: 0 14px 30px rgba(255, 51, 84, 0.25);
     }

     .secondary {
       background: rgba(255, 255, 255, 0.06);
       color: var(--text);
       border: 1px solid rgba(255, 255, 255, 0.08);
     }

     .status {
       min-height: 1.5em;
       color: #ffb6c1;
       font-size: 0.95rem;
     }

     .details-card h2 {
       font-size: 1rem;
       color: #cdd6f8;
       margin-bottom: 18px;
       letter-spacing: 0.04em;
       text-transform: uppercase;
     }

     .detail-list {
       display: grid;
       gap: 16px;
     }

     .detail {
       padding: 16px 18px;
       border-radius: 16px;
       background: rgba(255, 255, 255, 0.035);
       border: 1px solid rgba(255, 255, 255, 0.05);
     }

     .detail span {
       display: block;
       color: var(--muted);
       font-size: 0.86rem;
       margin-bottom: 6px;
     }

     dialog {
       width: min(92vw, 460px);
       padding: 0;
       border: 1px solid rgba(255, 255, 255, 0.08);
       border-radius: 24px;
       background: linear-gradient(180deg, rgba(20, 28, 48, 0.98), rgba(13, 18, 31, 0.98));
       color: var(--text);
       box-shadow: 0 40px 100px rgba(0, 0, 0, 0.65);
     }

     dialog::backdrop {
       background: rgba(4, 7, 14, 0.72);
       backdrop-filter: blur(6px);
     }

     .modal-content {
       padding: 28px;
     }

     .modal-header {
       display: flex;
       align-items: start;
       justify-content: space-between;
       gap: 16px;
       margin-bottom: 16px;
     }

     .modal-header h2 {
       font-size: 1.35rem;
       line-height: 1.2;
     }

     .icon-wrap {
       width: 48px;
       height: 48px;
       flex: 0 0 auto;
       border-radius: 16px;
       display: grid;
       place-items: center;
       background: rgba(255, 93, 115, 0.12);
       color: #ff8ea0;
     }

     .modal-copy {
       color: var(--muted);
       line-height: 1.7;
       margin-bottom: 24px;
     }

     .modal-actions {
       display: flex;
       justify-content: flex-end;
       gap: 12px;
       flex-wrap: wrap;
     }

     .close-icon {
       min-width: 44px;
       min-height: 44px;
       border-radius: 14px;
       background: transparent;
       color: #d0d8f5;
     }

     .danger {
       background: linear-gradient(180deg, var(--danger) 0%, var(--danger-strong) 100%);
       color: white;
     }

     .deleted .preview-image {
       filter: grayscale(1) brightness(0.55);
